diff --git a/src/lib/OpenEXRCore/internal_ht_common.cpp b/src/lib/OpenEXRCore/internal_ht_common.cpp
index 73668aed..58a67a96 100644
--- a/src/lib/OpenEXRCore/internal_ht_common.cpp
+++ b/src/lib/OpenEXRCore/internal_ht_common.cpp
@@ -309,11 +309,14 @@ read_header (
     for (size_t i = 0; i < map.size (); i++)
     {
         uint16_t file_index = header.pull_uint16 ();
-        if (file_index >= map.size() || map.at (file_index).scratch > 0)
-            throw std::runtime_error (
-                "HTJ2K chunk header contains invalid file_index values.");
+        if (file_index < map.size ())
+        {
+            if (map.at (file_index).scratch > 0)
+                throw std::runtime_error (
+                    "HTJ2K chunk header contains duplicate file_index values.");
+            map.at (file_index).scratch = 1;
+        }
         map.at (i).file_index = file_index;
-        map.at (file_index).scratch = 1;
     }

     return prefix_sz + payload_sz;

